using System.Globalization;
using Microsoft.CodeAnalysis;
using NUnit.Framework;

namespace SharpProof.Analyzer.Test;

[TestFixture]
public sealed class GeneratedCodeAnalyzerTests
{
    [TestCase("advisory")]
    [TestCase("strict")]
    public async Task SelectedGeneratedMethodIsAnalyzedAndReported(
        string profile)
    {
        var diagnostics = await AnalyzerTestHost.AnalyzeAsync(
            """
            // <auto-generated />
            using SharpProof.Attributes;

            internal static class GeneratedSubject {
                private static int State;

                [EnforcePure]
                internal static void Selected() {
                    State = 1;
                }
            }
            """,
            mode: null,
            enabledIds: ["SP0002"],
            profile: profile,
            features: "effects",
            filePath: "GeneratedSubject.g.cs");

        AnalyzerTestHost.AssertIds(diagnostics, "SP0002");
        Assert.That(
            diagnostics.Single().Location.SourceTree?.FilePath,
            Is.EqualTo("GeneratedSubject.g.cs"));
    }

    [Test]
    public async Task SelectedGeneratedMethodAnalyzesReachableNestedRequiresCalls()
    {
        var diagnostics = await AnalyzerTestHost.AnalyzeAsync(
            """
            // <auto-generated />
            using SharpProof.Attributes;

            internal static class GeneratedSubject {
                private static int Positive(int value) {
                    Contract.Requires(value > 0);
                    return value;
                }

                [return: Positive]
                internal static int Selected() {
                    return Reachable();

                    int Reachable() => Positive(-1);
                }
            }
            """,
            mode: null,
            enabledIds: ["SP0027"],
            profile: "strict",
            features: "contracts",
            filePath: "GeneratedSubject.g.cs");

        AnalyzerTestHost.AssertIds(diagnostics, "SP0027");
    }

    [Test]
    public async Task SelectedGeneratedExceptionHandlersUseManagedReachability()
    {
        var diagnostics = await AnalyzerTestHost.AnalyzeAsync(
            """
            // <auto-generated />
            using System;
            using SharpProof.Attributes;

            internal static class GeneratedSubject {
                private static int State;

                [EnforcePure]
                internal static void EmptyTry() {
                    try { }
                    catch { State = 1; }
                }

                [EnforcePure]
                internal static void ReachableCatch() {
                    try { throw new InvalidOperationException(); }
                    catch (InvalidOperationException) { State = 2; }
                }
            }
            """,
            mode: null,
            enabledIds: ["SP0002"],
            profile: "strict",
            features: "effects",
            filePath: "GeneratedSubject.g.cs");

        AnalyzerTestHost.AssertIds(diagnostics, "SP0002");
        Assert.That(
            diagnostics.Single().Location.GetLineSpan().StartLinePosition.Line,
            Is.EqualTo(14));
    }

    [Test]
    public async Task SelectedGeneratedArrayStoresUseExactRuntimeElementType()
    {
        var diagnostics = await AnalyzerTestHost.AnalyzeAsync(
            """
            // <auto-generated />
            using SharpProof.Attributes;

            internal static class GeneratedSubject {
                [DoesNotThrow]
                internal static void ExactStore() {
                    object[] values = new object[1];
                    values[0] = "value";
                }

                [DoesNotThrow]
                internal static void CovariantStore() {
                    object[] values = new string[1];
                    values[0] = new object();
                }
            }
            """,
            mode: null,
            enabledIds: ["SP0046"],
            profile: "strict",
            features: "effects",
            filePath: "GeneratedSubject.g.cs");

        AnalyzerTestHost.AssertIds(diagnostics, "SP0046");
        Assert.That(
            diagnostics.Single().GetMessage(CultureInfo.InvariantCulture),
            Does.Contain("'CovariantStore'"));
    }

    [Test]
    public async Task SelectedGeneratedInterpolationUsesTheOrdinaryShapeBoundary()
    {
        var diagnostics = await AnalyzerTestHost.AnalyzeAsync(
            """
            // <auto-generated />
            using System.Runtime.CompilerServices;
            using SharpProof.Attributes;

            [InterpolatedStringHandler]
            internal struct CustomHandler {
                internal CustomHandler(int literalLength, int formattedCount) { }
                internal void AppendLiteral(string value) { }
                internal void AppendFormatted<T>(T value) { }
            }

            internal static class GeneratedSubject {
                internal static void Consume(CustomHandler handler) { }

                [ZeroAllocations]
                internal static string Constant() => $"sharp";

                [ZeroAllocations]
                internal static string Runtime(string value) => $"{{{value}}}";

                [ZeroAllocations]
                internal static string Aligned(string value) => $"{value,4}";

                [ZeroAllocations]
                internal static void Custom() => Consume($"value={1}");
            }
            """,
            mode: null,
            enabledIds: ["SP0045", "SP0047"],
            profile: "strict",
            features: "effects",
            filePath: "GeneratedSubject.g.cs");

        Assert.That(
            diagnostics.Select(static diagnostic => diagnostic.Id),
            Is.EquivalentTo(["SP0045", "SP0047", "SP0047"]));
        Assert.That(
            diagnostics.Any(diagnostic =>
                diagnostic.GetMessage(CultureInfo.InvariantCulture)
                    .Contains("'Constant'", StringComparison.Ordinal)),
            Is.False);
    }

